import Foundation

/// Pip the Pin's five approved states (Figma `Mascot / Pip the Pin`, 25:101).
///
/// Pip is decoration. Nothing the driver needs to know is carried by the
/// mood alone: the meter hero states it in words, shape, and colour.
enum PipMood: String, CaseIterable, Sendable {
    case idle
    case nudge
    case sleepy
    case alarm
    case happy

    /// Image set in `Assets.xcassets/Mascot`, generated by
    /// `scripts/generate_pip_assets.py`.
    var assetName: String {
        "Pip" + rawValue.prefix(1).uppercased() + rawValue.dropFirst()
    }

    /// Pip perks up at the second free reminder, 5 minutes before expiry.
    static let alarmThreshold: TimeInterval = 5 * 60

    /// Pip on the Park screen for the active session.
    ///
    /// No meter, or plenty of time left: Pip naps on the saved spot. Inside
    /// the 15-minute warning window Pip leans in, and from 5 minutes left —
    /// including after expiry — Pip is on alert.
    static func forActiveSession(meterExpiry: Date?, now: Date) -> PipMood {
        guard let meterExpiry else { return .sleepy }
        let remaining = meterExpiry.timeIntervalSince(now)
        if remaining <= alarmThreshold { return .alarm }
        if remaining <= MeterState.warningThreshold { return .nudge }
        return .sleepy
    }
}
